        () => {
          // console.log('orientationchange:', e)
          this.setViewerClass('resize')
          // this.resetStereoAndScreen()
          this.__resetStereoAndScreen()
        },
        false
      )
    }
    const id = this.$route.params.id || 0
    const token = this.$route.params.token || null
    if (this.$route.query.type) {
      this.isCreatorPreview = true
    }
    if (token) {
      this.getProductByToken(token)
    } else {
      this.getProduct(id, this.onInitProductCall)
    }
