  watch: {
    toggleVRSlots(newVal, oldVal) {
      if (newVal !== oldVal) {
        if (this.vrViewer) {
          if (newVal) {
            this.vrViewer.navbar.show()
          } else {
            this.vrViewer.navbar.hide()
          }
        }
      }
