  },
  methods: {
    /**
     * 异步获取产品详情
     * 根据产品ID和当前路由来决定使用哪种方式获取产品详情
     * 此函数也支持传入一个可选的回调函数，在产品详情获取完毕后执行
     *
     * @param {number} id - 产品的ID，用于查询产品详情
     * @param {function} callback - （可选）在产品详情获取完毕后执行的回调函数
     */
    async getProduct(id, callback = null) {
      if (this.$route.name === 'VRView') {
        // 创作者获取作品详情
        this.product = await viewProduct(id, {
          creator_view: this.isCreatorPreview ? 1 : 0,
        })
      } else {
        // 对外开放获取作品详情
        this.product = await showVRProduct(id)
      }

      typeof callback === 'function' && callback()
    },
    /**
     * 通过token获取作品详情
     * @param token
     */
    async getProductByToken(token) {
      this.product = await checkShareToken(token)
      this.onInitProductCall()
    },
    /**
     * 初始化作品详情
     */
    onInitProductCall() {
      if (this.product.password) {
        if (
          this.$route.name === 'VRView' &&
          parseInt(this.product.userId) === parseInt(this.vip.id)
        ) {
          // 登录状态下,自己查看自己的作品无须访问密码验证
          return this.loadConfig()
        }

        this.viewPassword = true
        return this.openViewPasswordConfirm()
      }
      // this.getProductConfig('product_ad', (config) => {
      //   this.productAdConfig = config ? config.val : null
      // })
      // this.getProductConfig('begin_style', (config) => {
      //   this.productBeginStyleConfig = config ? config.val : null
      // })
      // this.getProductConfig('begin_cover', (config) => {
      //   this.productBeginCoverConfig = config ? config.val : null
      // })
      this.loadConfig()
      // 初始化平面地图
      this.getMapPlaneGraph()
    },
    /**
     * 弹出访问密码确认框
     */
    openViewPasswordConfirm() {
      this.$prompt('请输入访问密码', '提示', {
        confirmButtonText: '确定',
        showCancelButton: false,
        inputType: 'password',
        closeOnPressEscape: false,
        closeOnHashChange: false,
        closeOnClickModal: false,
        inputPattern: /\S+/,
        inputErrorMessage: '密码必须输入',
      })
        .then(({ value }) => {
          const admin = encryptProductId(this.product.id)
          const pwd = md5ProductViewPwd(admin, value)
          // eslint-disable-next-line no-unused-vars
          validateProductPwd(admin, pwd)
            // eslint-disable-next-line no-unused-vars
            .then(() => {
              this.viewPassword = false
              setTimeout(() => {
                this.loadConfig()
              }, 200)
            })
            .catch(() => {
              this.openViewPasswordConfirm()
            })
        })
        .catch(() => {})
    },
    /**
     * 加载配置
     */
    loadConfig() {
      this.productBeginCoverConfig =
        this.product['configs']['begin_cover'] ?? null
      this.productAdConfig = this.product['configs']['product_ad'] ?? null
      this.productBeginStyleConfig =
        this.product['configs']['begin_style'] ?? null
      this.productWatermarkConfig =
        this.product['configs']['product_watermark'] ?? null
      if (this.productBeginStyleConfig) {
        this.useIntroEntrance = Boolean(
          this.productBeginStyleConfig.use_intro_entrance
        )
        this.introAutoRate = Boolean(
          this.productBeginStyleConfig.intro_auto_rate
        )
      }
      if (
        this.productWatermarkConfig &&
        this.productWatermarkConfig.status === 1 &&
        this.productWatermarkConfig.content
      ) {
        Watermark.set(this.productWatermarkConfig.content)
      }

      // 加载首个场景配置
      if (this.product.scenes.length) {
        this.currentScene = this.product.scenes[0]
      }

      this.initView()
      // Promise.all([
      //   getProductConfig(this.product.id, 'begin_cover'),
      //   getProductConfig(this.product.id, 'product_ad'),
      //   getProductConfig(this.product.id, 'begin_style'),
      //   getProductConfig(this.product.id, 'product_watermark'),
      // ])
      //   .then((results) => {

      //   })
      //   .catch((error) => {
      //     console.error(error)
      //   })
    },
    /**
     * 初始化VR
     */
    initView() {
      if (
        this.productBeginCoverConfig &&
        (this.productBeginCoverConfig.pc_img ||
          this.productBeginCoverConfig.mobile_img)
      ) {
        this.renderVRState = false
        this.$refs.entry.src = this.adCoverImg
        // 加载入场广告
        const preventTouchMove = (ev) => {
          ev.preventDefault()
        }
        // 禁用默认触摸移动行为
        document.body.addEventListener('touchmove', preventTouchMove, {
          passive: false,
        })

        if (this.productBeginCoverConfig.entry_mode === 'auto') {
          this.beginAdCoverTimer = setInterval(() => {
            if (this.beginCoverEntryTime-- <= 0) {
              return this.stopBeginCoverAndRenderVR(preventTouchMove)
            }
          }, 1000)
        }
      } else {
        this.renderVRState = true
        this.$nextTick(() => {
          this.renderVR()
        })
      }
    },
    /**
     * 停止入场广告并渲染VR
     */
    stopBeginCoverAndRenderVR(preventTouchMove = null) {
      this.renderVRState = true
      this.beginAdCoverTimer && clearInterval(this.beginAdCoverTimer)
      if (preventTouchMove) {
        document.body.removeEventListener('touchmove', preventTouchMove)
      } else {
        document.body.ontouchmove = null
      }
      // document.body.ontouchmove = function (ev) {
      //   ev.stopPropagation()
      // }
      this.$nextTick(() => {
        this.renderVR()
      })
    },
    /**
     * 渲染VR后回调
     */
    renderVRCallback() {
      this.vrViewer.overlay.hide()
      this.isRenderGalleryComponent = true
      this._applyVrPlayOptions()
      this.initPluginAndBindEvent()
      if (this.currentScene) {
        this.initSceneHotPoints(
          this.currentScene.id,
          () => {
            this.renderAdMarkers()
            setTimeout(() => {
              const animateIcon = new AnimateIcon(50, 0.5, 21)
              animateIcon.begin()
            }, 500)
          },
          {
            useAiHuman: true,
          }
        )
      }
      // this.vrViewer.addEventListener(events.RenderEvent.type, this.vrOnRender)
      this.renderMapPlaneGraph()
    },
    renderAdMarkers() {
      // 开场提示
      if (this.productBeginStyleConfig && this.productBeginStyleConfig.img) {
        const that = this
        const img = new Image()
        img.src = this.productBeginStyleConfig.img_full
        img.onload = function () {
          console.log('开场提示图片加载完成')
          that.markersPlugin.addMarker({
            id: 'product_begin_style_img_full',
            size: { width: this.width / 2, height: this.height / 2 },
            image: that.productBeginStyleConfig.img_full,
            position: {
              yaw: that.vrOptions.defaultYaw,
              pitch: that.vrOptions.defaultPitch,
            },
            opacity: 1,
          })
          const showTimeIndex = setTimeout(() => {
            try {
              that.markersPlugin.removeMarker('product_begin_style_img_full')
              // eslint-disable-next-line no-empty
            } catch (_e) {}
            clearTimeout(showTimeIndex)
          }, 1000 * that.productBeginStyleConfig.show_time)
        }
      }

      // 地面遮罩
      if (this.productAdConfig && this.productAdConfig.bottom_mask_img_full) {
        console.log('地面遮罩:', this.productAdConfig.bottom_mask_img_full)
        this.markersPlugin.addMarker({
          id: 'product_ad_bottom_mask_img_full',
          size: { width: 200, height: 200 },
          // position: { yaw: 0, pitch: -Math.PI / 2 },
          // image: this.productAdConfig.bottom_mask_img_full,
          // opacity: 0.5,
          position: [
            { yaw: (7 * Math.PI) / 4, pitch: -Math.PI / 3 },
            { yaw: Math.PI / 4, pitch: -Math.PI / 3 },
            { yaw: (3 * Math.PI) / 4, pitch: -Math.PI / 3 },
            { yaw: (5 * Math.PI) / 4, pitch: -Math.PI / 3 },
          ],
          imageLayer: this.productAdConfig.bottom_mask_img_full,
          opacity: 0.5,
        })
      }
    },
    /**
     * 初始化VR后初始化插件
     */
    initPluginAndBindEvent() {
      this.markersPlugin = this.vrViewer.getPlugin(MarkersPlugin)
      this.autoRotatePlugin = this.vrViewer.getPlugin(AutorotatePlugin)
      this.overlaysPlugin = this.vrViewer.getPlugin(OverlaysPlugin)
      this.stereoPlugin = this.vrViewer.getPlugin(CustomerStereoPlugin)
      this.mapPlugin = this.vrViewer.getPlugin(MapPlugin)
      this.planPlugin = this.vrViewer.getPlugin(PlanPlugin)
      this.vrViewer.navbar.getButton('markers') &&
        this.vrViewer.navbar.getButton('markers').destroy()
      this.vrViewer.navbar.getButton('markersList') &&
        this.vrViewer.navbar.getButton('markersList').destroy()
      this.vrViewer.addEventListener(events.ReadyEvent.type, this.vrOnReady, {
        once: true,
      })
      // this.vrViewer.addEventListener('position-updated', ({ position }) => {
      //   console.log(
      //     `new position is yaw: ${position.yaw} pitch: ${position.pitch}`
      //   )
      // })
      // eslint-disable-next-line no-unused-vars
      this.vrViewer.addEventListener('click', () => {
        // console.log('showMarkerInfoDialog:', this.showMarkerInfoDialog)
        if (this.showMarkerInfoDialog) {
          return true
        }

        // console.log('vrViewer click event:', event)
        this.toggleVRSlots = !this.toggleVRSlots
        // if (this.introIsInit) {
        //   this.vrIntro(data.pitch, data.yaw)
        // }
      })
      this.vrViewer.addEventListener('dblclick', () => {
        console.log('double click')
        // this.introAutoRate = false
        this.autoRotatePlugin.config.autostartOnIdle = false
        this.autoRotatePlugin.stop()
      })
      this.markersPlugin.addEventListener(
        'select-marker',
        ({ marker, doubleClick }) => {
          return this.onClickMarker(marker, doubleClick)
          // if (marker.id === 'promotional_video_1') {
          //   if (marker.video.paused) {
          //     // marker.video.volume = 1.0
          //     // marker.video.muted = false
          //     marker.video.play()
          //   } else {
          //     marker.video.volume = 0
          //     marker.video.muted = true
          //     marker.video.pause()
          //   }
          // }
        }
      )

      this.mapPlugin.addEventListener('view-changed', ({ view }) => {
        if (view === 'maximized') {
          this.autoRotatePlugin.config.autostartOnIdle = false
          this.autoRotatePlugin.stop()
          this.toggleVRSlots = false
        } else {
          this.toggleVRSlots = true
        }
      })
      if (this.planPlugin) {
        this.planPlugin.addEventListener('view-changed', ({ view }) => {
          if (view === 'maximized') {
            this.autoRotatePlugin.config.autostartOnIdle = false
            this.autoRotatePlugin.stop()
            this.toggleVRSlots = false
          } else {
            this.toggleVRSlots = true
          }
        })
      }

      this.mapPlugin.addEventListener('select-hotspot', async (event) => {
        // console.log(`Clicked on hotspot:`, event)
        const hotspots = event.currentTarget.config.hotspots
        const hotspot = hotspots.find((item) => item.id === event.hotspotId)
        if (hotspot && hotspot.sceneId) {
          const scene = await getScene(hotspot.sceneId)
          this.gotoScene(scene)
        }
      })
      if (this.useIntroEntrance) {
        this.vrViewer.setOptions({
          defaultPitch: this.animatedValues.pitch.start,
          defaultYaw: this.animatedValues.yaw.start,
          defaultZoomLvl: this.animatedValues.zoom.start,
          maxFov: this.animatedValues.maxFov.start,
          fisheye: this.animatedValues.fisheye.start,
        })
      }
    },
    // 点击marker事件
    // eslint-disable-next-line no-unused-vars
    async onClickMarker(marker, doubleClick) {
      if (marker.type === 'videoLayer') {
        if (doubleClick) {
          this.showMarkerInfoDialog = true
          this.toggleVRSlots = false
          marker.video.muted = true
          marker.video.pause()
          this.$refs.markerShow.open(
            {
              hotType: 'video',
              videoUrl: marker.definition,
            },
            '100%',
            true,
            '10px'
          )
        } else {
          if (marker.video.paused) {
            marker.video.muted = false
            marker.video.play()
          } else {
            marker.video.volume = 0
            marker.video.muted = true
            marker.video.pause()
          }
        }
        // marker.video.setAttribute('controls', 'controls')
        // console.log(' marker.video:',  marker.video)
        // if (marker.video.requestFullscreen) {
        //   marker.video.requestFullscreen()
        // } else if (marker.video.webkitRequestFullscreen) { // Safari
        //   marker.video.webkitRequestFullscreen()
        // } else if (marker.video.msRequestFullscreen) { // IE11
        //   marker.video.msRequestFullscreen()
        // }
        return
      }
      if (!('data' in marker)) {
        return
      }
      const { data: config } = marker
      // console.log('marker:', config)
      if (config.hotType === 'hyperlink') {
        return window.open(config.link, config.linkTarget || '_blank')
      }

      if (config.hotType === 'sceneChange') {
        const toScene = await getScene(config.toSceneId)
        if (toScene) {
          return this.$refs.gallery.handleSceneChange(toScene)
        }
      }

      if (['text', 'video', 'image'].includes(config.hotType)) {
        this.toggleVRSlots = false
        this.showMarkerInfoDialog = true
        return this.$refs.markerShow.open(config, '80%')
      }

      if (config.hotType === 'iot') {
        this.toggleVRSlots = false
        this.showMarkerInfoDialog = true
        const device = await getDeviceInfo(config.iotDevice.device_full_id)
        if (device.device_type === 'camera') {
          // 监控 80%
          return this.$refs.cameraShow.open(device, '1152px')
        }
        // sensor 传感器
        return this.$refs.iotShow.open(device, '1152px')
      }
    },
    // vr加载完成事件
    vrOnReady() {
      this.vrViewerLoaded = true
      console.log(`viewer is ready`)
      if (this.useIntroEntrance) {
        this.vrViewer.navbar.hide()
        setTimeout(() => {
          if (this.introIsInit) {
            this.vrIntro(
              this.animatedValues.pitch.end,
              this.animatedValues.pitch.end
            )
          }
        }, 500)
      }

      // 修改默认按钮
      this.changeNavBars()
      // web XR
      this.initWebXR()
    },
    async getMapPlaneGraph() {
      const mapPlaneGraph = await getPlaneGraph(this.product.id)
      // console.log('mapPlaneGraph:', mapPlaneGraph)
      this.mapPlaneGraph = mapPlaneGraph
      if (mapPlaneGraph && mapPlaneGraph.type === 'gis') {
        return this.renderPlanMap()
      }
    },
    renderMapPlaneGraph() {
      if (!this.mapPlaneGraph) {
        return
      }

      if (this.mapPlaneGraph.type !== 'default') {
        return
      }

      if (!this.mapPlaneGraph.imgUrl) {
        return
      }
      if (!this.mapPlaneGraph.center) {
        return
      }
      const { position, scale } = this.mapPlaneGraph.center
      this.mapPlugin.setImage(this.mapPlaneGraph.imgUrlFull, {
        x: position.x * (1 / scale.scaleW),
        y: position.y * (1 / scale.scaleH),
      })

      this.mapPlugin.setZoom(100 * scale.scaleW)
      if (this.mapPlaneGraph.markers.length) {
        const markers = this.mapPlaneGraph.markers.map((item) => {
          const { x, y } = item.position
          const { scaleW, scaleH } = item.scale
          item['x'] = x * (1 / scaleW)
          item['y'] = y * (1 / scaleH)
          return item
        })
        // console.log('markers:', markers)
        this.mapPlugin.setHotspots(markers)
      }
    },
    renderPlanMap() {
      if (!this.mapPlaneGraph.imgUrl || !this.mapPlaneGraph.gisParam) {
        return
      }
      // eslint-disable-next-line no-unused-vars
      const { center, zoom_config, tiles } = this.mapPlaneGraph.gisParam
      if (!center) {
        return
      }

      const tilesUrlList = this.mapPlaneGraph.imgUrl.split('\n')

      if (tilesUrlList.length) {
        const layers = []
        tilesUrlList.forEach((item) => {
          layers.push(
            new TileLayer(
              item,
              Object.assign(
                {
                  maxZoom: zoom_config.max,
                  minZoom: zoom_config.min,
                },
                tiles.options
              )
            )
          )
        })
        const defaultZoom = parseFloat(zoom_config.zoom)

        const position = [parseFloat(center[0]), parseFloat(center[1])]
        this.vrPlugins.push([
          PlanPlugin,
          {
            defaultZoom: defaultZoom,
            // coordinates: position,
            configureLeaflet: (map) => {
              map.addLayer(new LayerGroup(layers))
              // console.log('map:', map)
              setTimeout(() => {
                if (zoom_config.max) {
                  console.log('setMaxZoom')
                  map.setMaxZoom(parseFloat(zoom_config.max))
                }
                if (zoom_config.min) {
                  console.log('setMinZoom')
                  map.setMinZoom(parseFloat(zoom_config.min))
                }
                if (zoom_config.zoom_delta) {
                  console.log('zoomDelta')
                  map.keyboard._setZoomDelta(
                    parseFloat(zoom_config.zoom_delta)
                  )
                }
                // if (zoom_config.zoom_snap) {
                //   console.log('zoomSnap')
                //   map.keyboard._setZoomSnap(parseFloat(zoom_config.zoom_snap))
                // }
                map.setView(position, defaultZoom, true)
                // console.log(
                //   'gis map:',
                //   map.getZoom(),
                //   defaultZoom,
                //   map.getCenter(),
                //   position
                // )
                const markerIcon = new Icon({
                  iconUrl: require('leaflet-draw/dist/images/marker-icon.png'),
                  iconSize: [25, 41],
                  iconAnchor: [22, 94],
                  popupAnchor: [-3, -76],
                  shadowUrl: require('leaflet-draw/dist/images/marker-shadow.png'),
                  shadowSize: [25, 41],
                  shadowAnchor: [22, 94],
                })
                // console.log('this.mapPlaneGraph.markers:', this.mapPlaneGraph.markers)
                this.mapPlaneGraph.markers.forEach((node) => {
                  // console.log('node:', node)
                  const marker = new Marker(
                    {
                      lat: node.position.y,
                      lng: node.position.x,
                    },
                    {
                      icon: markerIcon,
                    }
                  )
                    .bindPopup(node.sceneTitle, {
                      closeButton: false,
                      closeOnClick: false,
                      autoClose: false,
                      className: 'scene-marker-label',
                    })
                    .addTo(map)
                  // eslint-disable-next-line no-unused-vars
                  marker
                    // eslint-disable-next-line no-unused-vars
                    .addEventListener('click', (e) => {
                      this.planPlugin.close()
                      // this.planPlugin.minimize()
                      return this.onSceneChange(node)
                    })
                    .openPopup()
                })
                const markerRedIcon = new Icon({
                  iconUrl: require('@/assets/default/marker-y.png'),
                  iconSize: [25, 25],
                  iconAnchor: [22, 94],
                  popupAnchor: [-3, -76],
                  shadowUrl: require('leaflet-draw/dist/images/marker-shadow.png'),
                  shadowSize: [25, 41],
                  shadowAnchor: [22, 94],
                })
                this.hotpotMarkerItems.forEach((hotpot) => {
                  // console.log('hotpot:', hotpot)
                  const point =
                    this.vrViewer.dataHelper.sphericalCoordsToViewerCoords(
                      hotpot.position
                    )
                  //ContainerPointToLatLng
                  const latLng = map.containerPointToLatLng(point)
                  // console.log('latLng:', latLng)
                  const marker = new Marker(latLng, {
                    icon: markerRedIcon,
                  })
                    .bindPopup(hotpot.title, {
                      closeButton: false,
                      closeOnClick: false,
                      autoClose: false,
                      className: 'scene-marker-label',
                    })
                    .addTo(map)
                  marker
                  // eslint-disable-next-line no-unused-vars
                    .addEventListener('click', (e) => {
                      // this.planPlugin.minimize()
                      this.planPlugin.close()
                      return this.onClickMarker(hotpot)
                    })
                    .openPopup()
                })
              }, 500)
              // map._resetView(position, defaultZoom, true)
            },
            // layers: layers,
          },
        ])
      }
    },
