    /**
     * 初始化webvr
     */
    initWebXR() {
      // this.vrViewer.renderer.renderer.xr.enabled = true
    },
    // eslint-disable-next-line no-unused-vars
    stereo() {
      this.showWebVR()
    },
    /**
     *
     * @param dblclick
     */
    resetStereoAndScreen(dblclick = false) {
      if (this.stopStereo) {
        return
      }
      this.stopStereo = true
      const $el = document.documentElement
      if ($el.style.transform === `rotate(90deg)`) {
        $el.style.transform = `rotate(0)`
        $el.style.width = `100%`
        $el.style.height = `100%`
        this.$refs.viewer.style.width = '100vw'
        this.$refs.viewer.style.height = '100vh'
        this.setViewerClass()
        this.vrViewer.autoSize()
      }
      if (this.stereoing) {
        if (this.windowIsPortraitScreen() || dblclick) {
          this.stereoPlugin.stop(false)
          this.stereoing = false
          this.stopStereo = false
        }
      }
      this.stopStereo = false
    },
    setViewerClass(type = 'init') {
      const pageInfo = this.getWindowConfig()
      if (type === 'init') {
        this.clientHeight = pageInfo.windowHeight
      }
    },
    getWindowConfig() {
      let windowWidth = window.innerWidth
      let windowHeight = window.innerHeight
      if (typeof windowWidth !== 'number') {
        if (document.compatMode === 'CSS1Compat') {
          windowWidth = document.documentElement.clientWidth
          windowHeight = document.documentElement.clientHeight
        } else {
          windowWidth = document.body.clientWidth
          windowHeight = window.body.clientHeight
        }
      }
      return {
        windowWidth: windowWidth,
        windowHeight: windowHeight,
      }
    },
    setMobilePageHeight() {
      if (isMobile()) {
        let pageInfo = this.getWindowConfig()
        this.$refs.viewer.style.height = pageInfo.pageHeight - 46 + 'px'
      }
    },
    windowIsPortraitScreen() {
      return (
        window.orientation == null ||
        window.orientation === 180 ||
        window.orientation === 0
      )
    },
    windowIsLandscapeScreen() {
      return window.orientation === 90 || window.orientation === -90
    },
    showWebVR() {
      if (!this.vrViewer) {
        return
      }

      const $el = document.documentElement
      const { windowWidth: width, windowHeight: height } =
        this.getWindowConfig()
      if ($el.style.transform === `rotate(90deg)`) {
        // 已经是伪全屏
        console.log('伪全屏')
        this.resetStereoAndScreen()
        return
      }

      if ((isMobile() || isSafari()) && this.windowIsPortraitScreen()) {
        // 竖屏
        console.log('竖屏')
        $el.style.transform = `rotate(90deg)`
        $el.style.width = `${height}px`
        $el.style.height = `${width}px`
        this.$refs.viewer.style.width = '100%'
        this.$refs.viewer.style.height = '100%'
        $el.style.transformOrigin = `${width / 2}px center`
        this.agentClass = ''
        this.vrViewer.autoSize()
      }
      if (this.windowIsLandscapeScreen()) {
        console.log('横屏状态')
      }

      if (!this.stereoing) {
        this.stereoPlugin.start(false)
        this.stereoing = true
      }
    },
    createVideoLayer(videoData) {
      this.markersPlugin.addMarker({
        id: videoData.id,
        videoLayer: videoData.url,
        position: [
          { pitch: 0.22956473544774392, yaw: 5.5495489509206575 }, // 左上
          { pitch: 0.24231234867034335, yaw: 6.038186888080926 }, // 右上
          { pitch: -0.07556436817552536, yaw: 6.033915892015927 }, // 右下
          { pitch: -0.08764006493781573, yaw: 5.547753988492682 }, // 左下
        ],
        size: { width: 640, height: 380 },
        style: {
          cursor: 'pointer',
        },
        chromaKey: {
          enabled: true,
          color: '#014EF2',
          similarity: 0.1,
        },
        tooltip: 'Play / Pause',
      })

      const video = this.markersPlugin.getMarker(videoData.id).video
      setTimeout(() => {
        video.currentTime = 0
        video.autoplay = false
        video.muted = false
      }, 4000)
    },
    onVideoFullScreen(video) {
      // eslint-disable-next-line no-unused-vars
      let isFullscreen = false
      // console.log('dd:', this.vrViewer)
      // loader.container
      // eslint-disable-next-line no-unused-vars

      const toggleFullScreen = () => {
        if (!document.fullscreenElement) {
          // 进入全屏
          if (video.requestFullscreen) {
            video.requestFullscreen()
          } else if (video.mozRequestFullScreen) {
            /* Firefox */
            video.mozRequestFullScreen()
          } else if (video.webkitRequestFullscreen) {
            /* Chrome, Safari and Opera */
            video.webkitRequestFullscreen()
          } else if (video.msRequestFullscreen) {
            /* IE/Edge */
            video.msRequestFullscreen()
          }
        } else {
          // 退出全屏
          if (document.exitFullscreen) {
            document.exitFullscreen()
          } else if (document.mozCancelFullScreen) {
            /* Firefox */
            document.mozCancelFullScreen()
          } else if (document.webkitExitFullscreen) {
            /* Chrome, Safari and Opera */
            document.webkitExitFullscreen()
          } else if (document.msExitFullscreen) {
            /* IE/Edge */
            document.msExitFullscreen()
          }
        }
      }

      // 获取 Three.js 的场景元素
      // 监听 Three.js 场景的 dblclick 事件
      this.vrViewer.container.addEventListener('dblclick', function (event) {
        // console.log('dblclick:', event)
        // 检查事件目标是否是你的视频元素
        if (event.target === video) {
          toggleFullScreen()
        }
      })
      // 监听双击事件
      // video.removeEventListener('dblclick', handler)
      // video.addEventListener('dblclick', handler)
    },
    // vr render事件
    vrOnRender(event) {
      console.log('vrOnRender:', event)
    },
    // 小行星模式
    vrIntro(pitch = null, yaw = null) {
      this.introIsInit = false
      this.autoRotatePlugin.stop()
      this.vrViewer.navbar.show()
      if (!isNaN(this.vrOptions.defaultZoomLvl)) {
        this.animatedValues.zoom.end = this.vrOptions.defaultZoomLvl
      }
      this.animatedValues.pitch.end = this.vrOptions.defaultPitch
      this.animatedValues.yaw.end = this.vrOptions.defaultYaw
      if (pitch) {
        this.animatedValues.pitch.end = pitch
      }
      if (yaw) {
        this.animatedValues.yaw.end = yaw
      }
      // console.log('vrIntro:', this.vrOptions)
      new utils.Animation({
        properties: {
          ...this.animatedValues,
          pitch: {
            start: this.animatedValues.pitch.start,
            end: this.animatedValues.pitch.end,
          },
          yaw: {
            start: this.animatedValues.yaw.start,
            end: this.animatedValues.yaw.end,
          },
        },
        duration: 2500,
        easing: 'inOutQuad',
        onTick: (properties) => {
          this.vrViewer.setOptions({
            fisheye: properties.fisheye,
            maxFov: properties.maxFov,
          })
          this.vrViewer.rotate({
            yaw: properties.yaw,
            pitch: properties.pitch,
          })
          this.vrViewer.zoom(properties.zoom)
        },
      }).then(() => {
        if (this.introAutoRate) {
          this.autoRotatePlugin.setOptions({
            autorotatePitch: this.animatedValues.pitch.end,
            autorotateZoomLvl: this.vrOptions.defaultZoomLvl
              ? this.vrOptions.defaultZoomLvl
              : null,
            autostartDelay: 1000,
            autorotateSpeed: this.vrOptions.autorotateSpeed
              ? !isNaN(this.vrOptions.autorotateSpeed)
                ? `${this.vrOptions.autorotateSpeed}rpm`
                : this.vrOptions.autorotateSpeed
              : '0.5rpm',
            autostartOnIdle: true,
          })
          this.autoRotatePlugin.start()
        }
        this.vrViewer.navbar.show()
        this.vrViewer.setOptions({
          mousemove: true,
          mousewheel: true,
        })
      })
    },
    // 小行星模式重置
    vrIntroReset() {
      this.introIsInit = true
      this.autoRotatePlugin.stop()
      this.vrViewer.navbar.show()
      this.vrViewer.setOptions({
        mousemove: true,
        mousewheel: true,
      })
      // this.setVrFisheyeMode(false)

      new utils.Animation({
        properties: {
          pitch: {
            start: this.vrViewer.getPosition().pitch,
            end: this.animatedValues.pitch.start,
          },
          yaw: {
            start: this.vrViewer.getPosition().yaw,
            end: this.animatedValues.yaw.start,
          },
          zoom: {
            start: this.vrViewer.getZoomLevel(),
            end: this.animatedValues.zoom.start,
          },
          maxFov: {
            start: this.animatedValues.maxFov.end,
            end: this.animatedValues.maxFov.start,
          },
          fisheye: {
            start: this.animatedValues.fisheye.end,
            end: this.animatedValues.fisheye.start,
          },
        },
        duration: 1500,
        easing: 'inOutQuad',
        onTick: (properties) => {
          this.vrViewer.setOptions({
            fisheye: properties.fisheye,
            maxFov: properties.maxFov,
          })
          console.log('yaw:', properties.yaw, properties.pitch)
          this.vrViewer.rotate({
            yaw: properties.yaw,
            pitch: properties.pitch,
          })
          this.vrViewer.zoom(properties.zoom)
        },
      })
    },
    // 设置鱼眼视角
    setVrFisheyeMode(value) {
      const oldFisheye = this.vrViewer.fisheye
      if (oldFisheye === value) {
        return false
      }
      this.vrViewer.setOption('fisheye', value)
    },
    // 业务-关闭广告
    closeProductAd() {
      this.productAdConfig['status'] = 0
    },
    // 业务-跳转品牌链接
    jumpBrandWebsite() {
      if (this.product.brandWebsite) {
        return window.open(this.product.brandWebsite, '_blank')
      }
    },
    jumpAdWebsite() {
      if (this.productAdConfig && this.productAdConfig.link) {
        return window.open(
          this.product.brandWebsite,
          this.productAdConfig.link_target
        )
      }
    },
    // 业务-分享
    share() {
      this.$refs.shareQrCode.open(this.product.id)
    },
    // 业务-收藏
    addFavorite() {
      this.$message.alert('暂未开放')
    },
    likeProduct() {
      // this.$message.alert('暂未开放')
      likeProduct(this.product.id).then(() => {
        this.$message.success('点赞成功')
      })
    },
    shareProduct() {
      this.$message.alert('暂未开放')
    },
    showWebXR() {
      if (navigator.xr) {
        navigator.xr
          .requestSession('immersive-vr')
          .then((session) => {
            this.vrViewer.renderer.renderer.xr.setSession(session)
          })
          .catch((error) => {
            console.error('Failed to enter VR mode:', error)
            this.$message.warning(
              '对于具有头戴式虚拟现实跟踪功能的真实WebVR，请使用WebVR-capable浏览器或移动设备和虚拟现实设备.'
            )
          })
      } else {
        console.warn('WebXR not supported')
        this.$message.alert('暂未开放')
      }
    },
    // 场景列表加载
    onSceneListLoaded(firstScene) {
      this.currentScene = firstScene
      this.gotoScene(firstScene)
    },
    async onSceneChange(scene) {
      await this.gotoScene(scene)
    },
    async gotoScene(scene) {
      if (scene.id === this.currentScene.id) {
        console.log('same scene')
        return false
      }
      this.currentScene = scene
      this.vrViewer.overlay.show({
        text: '场景切换中',
        dissmisable: false,
      })
      this.vrIntroReset()
      this.vrViewer.renderer.container.querySelector(
        '.psv-canvas'
      ).style.display = 'none'
      await this.renderVR()
      this.toggleVRSlots = true
      this.vrIntro()
      await new Promise((resolve) => setTimeout(resolve, 1000))
      this.vrViewer.renderer.container.querySelector(
        '.psv-canvas'
      ).style.display = 'block'
    },
  },
}
</script>
  
