import {
    StereoPlugin,
    StereoUpdatedEvent,
    StereoEffect
} from '@photo-sphere-viewer/stereo-plugin'
import {
    events
} from '@photo-sphere-viewer/core'
import {
    utils
} from '@photo-sphere-viewer/core'

export default class CustomerStereoPlugin extends StereoPlugin {
    constructor(viewer) {
        super(viewer)
        this.pseudoFullScreen = false
    }
    isWechat() {
        return navigator.userAgent.toLowerCase().indexOf('micromessenger') != -1
    }
    start(fullScreen = true) {
        console.log('start stereo')
        // return super.start()
        if (fullScreen) {
            this.viewer.enterFullscreen()
            this.__startWakelock()
            this.__lockOrientation()
        }
        return this.gyroscope.start('fast').then(
            () => {
                this.viewer.renderer.setCustomRenderer((renderer) => new StereoEffect(renderer))
                this.state.enabled = true
                this.markers?.hideAllMarkers()
                this.compass?.hide()
                this.viewer.navbar.hide()
                this.viewer.panel.hide()
                this.dispatchEvent(new StereoUpdatedEvent(true))
                this.viewer.notification.show({
                    content: this.viewer.config.lang.stereoNotification,
                    timeout: 3000
                })
            },
            () => {
                this.__unlockOrientation()
                this.__stopWakelock()
                this.viewer.exitFullscreen()
                return Promise.reject()
            }
        )
    }
    stop(resetScreen = true) {
        console.log('stop stereo:')
        if (this.isEnabled()) {
            this.viewer.renderer.setCustomRenderer(null)
            this.state.enabled = false
            this.markers?.showAllMarkers()
            this.compass?.show()
            this.viewer.navbar.show()
            if (resetScreen) {
                this.__unlockOrientation()
                this.__stopWakelock()
                this.viewer.exitFullscreen()
                this.gyroscope.stop()
            }
            this.dispatchEvent(new StereoUpdatedEvent(false))
        }
    }
    destroy(resetScreen = true) {
        this.viewer.removeEventListener(events.StopAllEvent.type, this)
        this.viewer.removeEventListener(events.ClickEvent.type, this)
        this.stop(resetScreen)
        delete this.markers
        delete this.compass
        delete this.gyroscope
        super.destroy()
    }
    __lockOrientation() {
        let displayRotateMessageTimeout
        const ID_OVERLAY_PLEASE_ROTATE = 'pleaseRotate'
        const mobile_rotate_default = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><path fill="currentColor" d="M66.7 19a14 14 0 0 1 13.8 12.1l-3.9-2.7c-.5-.3-1.1-.2-1.4.3-.3.5-.2 1.1.3 1.4l5.7 3.9.6.2c.3 0 .6-.2.8-.4l3.9-5.7c.3-.5.2-1.1-.3-1.4-.5-.3-1.1-.2-1.4.3l-2.4 3.5A16 16 0 0 0 66.7 17c-.6 0-1 .4-1 1s.4 1 1 1zM25 15h10c.6 0 1-.4 1-1s-.4-1-1-1H25c-.6 0-1 .4-1 1s.4 1 1 1zm-6.9 30H16l-2 .2a1 1 0 0 0-.8 1.2c.1.5.5.8 1 .8h.2l1.7-.2h2.1c.6 0 1-.4 1-1s-.5-1-1.1-1zm10 0h-4c-.6 0-1 .4-1 1s.4 1 1 1h4c.6 0 1-.4 1-1s-.4-1-1-1zM84 45H55V16A11 11 0 0 0 44 5H16A11 11 0 0 0 5 16v68a11 11 0 0 0 11 11h68a11 11 0 0 0 11-11V56a11 11 0 0 0-11-11zM16 93c-5 0-9-4-9-9V53.2c.3-.1.6-.3.7-.6a9.8 9.8 0 0 1 2-3c.4-.4.4-1 0-1.4a1 1 0 0 0-1.4 0l-1.2 1.5V16c0-5 4-9 9-9h28c5 0 9 4 9 9v68c0 5-4 9-9 9H16zm77-9c0 5-4 9-9 9H50.3c2.8-2 4.7-5.3 4.7-9V47h29c5 0 9 4 9 9v28zM38.1 45h-4c-.6 0-1 .4-1 1s.4 1 1 1h4c.6 0 1-.4 1-1s-.5-1-1-1zm9.9 0h-4c-.6 0-1 .4-1 1s.4 1 1 1h4c.6 0 1-.4 1-1s-.4-1-1-1zm38 19c-.6 0-1 .4-1 1v10c0 .6.4 1 1 1s1-.4 1-1V65c0-.6-.4-1-1-1z"/><!--Created by Anthony Bresset from the Noun Project--></svg>'
        const displayRotateMessage = () => {
            if (window.innerHeight > window.innerWidth) {
                this.pseudoFullScreen = true
                if (this.isWechat()) {
                    console.log('wechat browser')
                } else {
                    if (utils.getOrientation() !== 'landscape' && !this.viewer.overlay.isVisible(ID_OVERLAY_PLEASE_ROTATE)) {
                        this.viewer.overlay.show({
                            id: ID_OVERLAY_PLEASE_ROTATE,
                            image: mobile_rotate_default,
                            title: this.viewer.config.lang.pleaseRotate,
                            text: this.viewer.config.lang.tapToContinue
                        })
                        this.state.waitLandscape = utils.waitLandscape(() => {
                            this.viewer.overlay.hide(ID_OVERLAY_PLEASE_ROTATE)
                            utils.cancelWaitLandscape(this.state.waitLandscape)
                            this.state.waitLandscape = null
                        })
                    }
                }
            }

            if (displayRotateMessageTimeout) {
                clearTimeout(displayRotateMessageTimeout)
                displayRotateMessageTimeout = null
            }
        }
        try {
            screen.orientation.lock('landscape').then(null, () => displayRotateMessage())
            displayRotateMessageTimeout = setTimeout(() => displayRotateMessage(), 1e3)
        } catch {
            displayRotateMessage()
        }
    }
}